import pandas as pd
import numpy as np

# Test 1: pyarrow float64 with non-null NaN
try:
    pa = __import__('pyarrow')
    df_pa = pd.DataFrame({
        'values': pd.array([5.0, np.nan, 1.0, 3.0, 2.0, 4.0], dtype=pd.ArrowDtype(pa.float64())),
        'key': ['a'] * 6
    })
    result_pa = df_pa.groupby('key')['values'].quantile([0.0, 0.25, 0.5, 0.75, 1.0])
    probe("DataFrame with pyarrow float64 column containing [5.0, NaN, 1.0, 3.0, 2.0, 4.0] (NaN is non-null value) grouped by key=['a']*6, calling quantile([0.0, 0.25, 0.5, 0.75, 1.0])", result_pa.tolist())
except Exception as e:
    probe("DataFrame with pyarrow float64 column containing [5.0, NaN, 1.0, 3.0, 2.0, 4.0] (NaN is non-null value) grouped by key=['a']*6, calling quantile([0.0, 0.25, 0.5, 0.75, 1.0])", "__error__: " + type(e).__name__ + ": " + str(e))

# Test 2: masked FloatingArray with non-null NaN
try:
    from pandas.arrays import FloatingArray
    import pandas.core.arrays.masked as masked_module

    # Create a FloatingArray with NaN but all-zero mask (meaning NaN is NOT masked, it's a valid non-null value)
    values = np.array([5.0, np.nan, 1.0, 3.0, 2.0, 4.0], dtype=np.float64)
    mask = np.array([False, False, False, False, False, False], dtype=bool)
    float_array = FloatingArray(values, mask)

    df_masked = pd.DataFrame({
        'values': float_array,
        'key': ['a'] * 6
    })
    result_masked = df_masked.groupby('key')['values'].quantile([0.0, 0.25, 0.5, 0.75, 1.0])
    probe("DataFrame with masked FloatingArray [5.0, NaN, 1.0, 3.0, 2.0, 4.0] with all-zero mask (NaN is non-null) grouped by key=['a']*6, calling quantile([0.0, 0.25, 0.5, 0.75, 1.0])", result_masked.tolist())
except Exception as e:
    probe("DataFrame with masked FloatingArray [5.0, NaN, 1.0, 3.0, 2.0, 4.0] with all-zero mask (NaN is non-null) grouped by key=['a']*6, calling quantile([0.0, 0.25, 0.5, 0.75, 1.0])", "__error__: " + type(e).__name__ + ": " + str(e))

# Test 3: all-NaT datetime group
try:
    df_datetime = pd.DataFrame({
        'dates': pd.to_datetime(['NaT', 'NaT', '2020-01-01', '2020-01-02']),
        'key': ['a', 'a', 'b', 'b']
    })
    result_datetime = df_datetime.groupby('key')['dates'].quantile(0.5)
    # Record the result for group 'a' (the all-NaT group)
    probe("DataFrame with datetime values [NaT, NaT, 2020-01-01, 2020-01-02] grouped by key=['a', 'a', 'b', 'b'], calling quantile(0.5) on group 'a' (all-NaT group)", result_datetime.loc['a'])
except Exception as e:
    probe("DataFrame with datetime values [NaT, NaT, 2020-01-01, 2020-01-02] grouped by key=['a', 'a', 'b', 'b'], calling quantile(0.5) on group 'a' (all-NaT group)", "__error__: " + type(e).__name__ + ": " + str(e))

